  if(L.length){h+='<div class="ntfil"><input class="field" id="ntQ" type="search" placeholder="Search notes" value="'+esc(NTV.q)+'" aria-label="Search notes"><button class="chipb'+(NTV.st?' on':'')+'" onclick="NTV.st=NTV.st?0:1;ntHome()" aria-pressed="'+!!NTV.st+'">★ Starred</button></div>';
    h+='<select aria-label="Chapter" onchange="NTV.ch=this.value;ntHome()"><option value="All">All chapters ('+L.length+')</option>'+Object.keys(chs).sort().map(function(c){return'<option value="'+esc(c)+'"'+(c===NTV.ch?' selected':'')+'>'+esc(c)+' ('+chs[c]+')</option>'}).join('')+'</select>'}
  if(!L.length)h+='<div class="card"><b>No notes yet</b><p class="sub" style="margin:4px 0 0">Good first notes: a formula you keep forgetting, a step that finally made sense, or a photo of your teacher’s board work.</p></div>';
  else if(!shown.length)h+='<div class="card"><p class="sub" style="margin:0">No notes match.</p></div>';
