isc('s',2,'The AM and GM of two positive numbers are 10 and 8. Find the numbers',['16 and 4','12 and 8','10 and 8','18 and 2'],0,',amgm,amgm,amgm','a + b = 20 and ab = 64, so the numbers are 16 and 4.');
isc('s',2,'Insert 3 arithmetic means between 3 and 19',['7, 11, 15','6, 11, 16','7, 11, 19','5, 9, 13'],0,',insertm,insertm,insertm','5 terms in all, so d = (19 − 3)/4 = 4: 7, 11, 15.');
Object.assign(TG,{
area:['Area of a triangle','Area = ½|x₁(y₂ − y₃) + x₂(y₃ − y₁) + x₃(y₁ − y₂)|. Halve it and take the modulus; zero area means collinear.'],
angle:['Angle between lines','tan θ = |(m₁ − m₂)/(1 + m₁m₂)|. Use the modulus for the acute angle.'],
parallel:['Distance between parallel lines','Make the x and y coefficients identical first, then d = |c₁ − c₂|/√(a² + b²).'],
intercept:['Intercept form','x/a + y/b = 1. With equal intercepts it becomes x + y = a; put in the point to find a.'],
image:['Image in a line','(x − x₁)/a = (y − y₁)/b = −2(ax₁ + by₁ + c)/(a² + b²). Keep the −2 and the sign of c.'],
normalf:['Normal form','x cos α + y sin α = p, where p is the perpendicular from the origin and α its angle with the x-axis.'],
external:['External division','For external ratio m:n use (mx₂ − nx₁)/(m − n). Minus signs replace the pluses.'],
tangent:['Tangent at a point','For x² + y² = a² the tangent at (x₁, y₁) is xx₁ + yy₁ = a².'],
tanlen:['Length of a tangent','Length = √S₁: put the point into the circle’s equation (right side 0), then take the square root.'],
touch:['Touching an axis','Touching the x-axis means radius = |k|; touching the y-axis means radius = |h|.'],
posn:['Position of a point','Put the point into S = x² + y² + …: S > 0 outside, S = 0 on, S < 0 inside.'],
double:['Double-angle formulas','sin 2A = 2 sin A cos A; cos 2A = (1 − tan²A)/(1 + tan²A) = 1 − 2sin²A.'],
general:['General solutions','sin θ = sin α: nπ + (−1)ⁿα. cos θ = cos α: 2nπ ± α. tan θ = tan α: nπ + α.'],
triple:['Triple-angle formulas','sin 3A = 3 sin A − 4 sin³A; cos 3A = 4 cos³A − 3 cos A.'],
sumprod:['Sum-to-product','sin C + sin D = 2 sin((C + D)/2) cos((C − D)/2). Halve the sum and the difference.'],
cosrule:['Cosine rule','cos C = (a² + b² − c²)/2ab. A negative cosine means an obtuse angle.'],
maxval:['Maximum of a sin x + b cos x','It ranges from −√(a² + b²) to √(a² + b²).']
});
isc('g',2,'Area of the triangle with vertices (1, 2), (4, 6) and (7, 2)',['12','24','−12','6'],0,',area,area,area','½|1(6 − 2) + 4(2 − 2) + 7(2 − 6)| = ½|−24| = 12.');
isc('g',2,'Find k if (k, 3), (2, 1) and (5, 7) are collinear',['3','−3','6','1'],0,',area,area,area','Area = 0: k(1 − 7) + 2(7 − 3) + 5(3 − 1) = −6k + 18 = 0, so k = 3.');
isc('g',2,'Acute angle between y = √3x + 5 and y = x/√3 − 2',['30°','60°','90°','45°'],0,',angle,angle,angle','The slopes are tan 60° and tan 30°, so the angle is 30°.');
isc('g',3,'Distance between 3x + 4y − 7 = 0 and 6x + 8y + 6 = 0',['2','13/10','1/5','10'],0,',parallel,parallel,pdist','Second line: 3x + 4y + 3 = 0. d = |−7 − 3|/5 = 2.');
isc('g',2,'Line through (2, 3) making equal intercepts on the axes',['x + y = 5','x − y = −1','2x + 3y = 13','x + y = 1'],0,',intercept,lineform,intercept','x + y = a with 2 + 3 = a, so x + y = 5.');
isc('g',3,'Image of (3, 8) in the line x + 3y = 7',['(−1, −4)','(1, 4)','(−1, 4)','(5, 20)'],0,',image,image,image','(x − 3)/1 = (y − 8)/3 = −2(3 + 24 − 7)/10 = −4, so (−1, −4).');
isc('g',3,'Line whose perpendicular from the origin has length 5 and makes 30° with the x-axis',['√3x + y = 10','x + √3y = 10','√3x + y = 5','√3x − y = 10'],0,',normalf,normalf,normalf','x cos 30° + y sin 30° = 5 gives √3x + y = 10.');
isc('g',2,'Point dividing (1, 2) and (4, 5) externally in the ratio 2 : 1',['(7, 8)','(3, 4)','(−2, −1)','(2, 3)'],0,',external,external,external','x = (2·4 − 1·1)/(2 − 1) = 7, y = (2·5 − 1·2)/1 = 8.');
isc('c',2,'Circle through (0, 0), (4, 0) and (0, 6)',['x² + y² − 4x − 6y = 0','x² + y² + 4x + 6y = 0','x² + y² − 4x − 6y − 13 = 0','x² + y² − 2x − 3y = 0'],0,',centresign,expandc,halve','Through the origin, so c = 0. The intercepts give 2g = −4 and 2f = −6.');
isc('c',2,'Tangent to x² + y² = 25 at (3, 4)',['3x + 4y = 25','4x + 3y = 25','3x + 4y = 5','3x − 4y = 25'],0,',tangent,tangent,tangent','xx₁ + yy₁ = a² gives 3x + 4y = 25.');
isc('c',3,'Length of the tangent from (5, 3) to x² + y² − 4x − 2y − 4 = 0',['2','4','√30','16'],0,',tanlen,tanlen,tanlen','S₁ = 25 + 9 − 20 − 6 − 4 = 4, so the length is √4 = 2.');
isc('c',3,'Circle with centre on the x-axis passing through (1, 1) and (3, 3)',['(x − 4)² + y² = 10','(x + 4)² + y² = 10','(x − 4)² + y² = 18','x² + (y − 4)² = 10'],0,',centresign,rsquare,centresign','(1 − h)² + 1 = (3 − h)² + 9 gives h = 4, and r² = 9 + 1 = 10.');
isc('c',3,'Values of k for which x + y = k touches x² + y² = 8',['±4','4 only','±8','±2√2'],0,',twoans,distance,distance','|k|/√2 = 2√2, so k = ±4.');
isc('c',2,'Circle with centre (2, 3) that touches the x-axis',['x² + y² − 4x − 6y + 4 = 0','x² + y² − 4x − 6y + 9 = 0','x² + y² − 4x − 6y + 11 = 0','x² + y² + 4x + 6y + 4 = 0'],0,',touch,expandc,centresign','r = 3, so the constant is 4 + 9 − 9 = 4.');
isc('c',1,'Where does (2, 3) lie relative to x² + y² = 10?',['Outside','Inside','On the circle','Cannot be decided'],0,',posn,posn,posn','S = 4 + 9 − 10 = 3 > 0, so outside.');
isc('t',1,'Value of sin 15° cos 15°',['1/4','1/2','√3/4','1/8'],0,',double,double,double','½ sin 30° = 1/4.');
isc('t',2,'Value of tan 15°',['2 − √3','2 + √3','√3 − 1','1/√3'],0,',compound,compound,compound','tan(45° − 30°) = (1 − 1/√3)/(1 + 1/√3) = 2 − √3.');
isc('t',2,'General solution of tan θ = √3',['θ = nπ + π/3','θ = 2nπ + π/3','θ = nπ ± π/3','θ = 2nπ ± π/3'],0,',general,general,general','tan repeats every π: θ = nπ + π/3.');
isc('t',2,'General solution of cos θ = 1/2',['θ = 2nπ ± π/3','θ = nπ + π/3','θ = nπ ± π/3','θ = 2nπ + π/3'],0,',general,general,general','cos θ = cos α gives θ = 2nπ ± α, with α = π/3.');
isc('t',2,'If tan θ = 3/4, find cos 2θ',['7/25','24/25','−7/25','1/25'],0,',double,double,double','(1 − 9/16)/(1 + 9/16) = 7/25.');
isc('t',1,'sin 3A in terms of sin A',['3 sin A − 4 sin³A','4 sin³A − 3 sin A','3 sin A + 4 sin³A','4 cos³A − 3 cos A'],0,',triple,triple,triple','sin 3A = 3 sin A − 4 sin³A.');
isc('t',3,'Value of sin 75° + sin 15°',['√6/2','√3/2','1','√2'],0,',sumprod,sumprod,sumprod','2 sin 45° cos 30° = 2(√2/2)(√3/2) = √6/2.');
isc('t',3,'In triangle ABC, a = 3, b = 5, c = 7. Find angle C',['120°','60°','30°','150°'],0,',cosrule,cosrule,cosrule','cos C = (9 + 25 − 49)/30 = −1/2, so C = 120°.');
isc('t',2,'Maximum value of 3 sin x + 4 cos x',['5','7','4','1'],0,',maxval,maxval,maxval','√(3² + 4²) = 5.');
var EMPTY=function(){var s={w:{},l:{},tg:{},ev:[],an:null,anAt:0,anN:0,tw:'',st:[],bx:{},pp:{},cb:{},int:'economics, political science, philosophy, music, piano, Spotify playlists, cricket'};Object.keys(NM).forEach(function(p){s.l[p]=1});return s};
var S=EMPTY(),DB=null,DOC=null,SMP=null,view='today',app=document.getElementById('app');
var mode,seen,log,n,cur,locked,N,GEN=null,busy=false;
function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
function tg(k){return TG[k]||S.tg[k]||[k,'']}
/* options are shown in a shuffled order that changes every time the app opens, so the right answer never sits in a fixed place.
   Handlers still receive the original index. Options that point at other options ("both of the above") keep their written order. */
var OPSALT=String(Math.random()).slice(2),OPC={};
function optPm(key,o){o=o||[];var n=o.length,ck=key+'|'+n;if(OPC[ck])return OPC[ck];var p=[],i;for(i=0;i<n;i++)p.push(i);
  var pin=n<3||o.some(function(t){return/\b(all|none|both|neither|either|any|each) of (the|these|them)\b|\babove\b|\bbelow\b|\bof these\b|\([a-dA-D]\)|\bA and R\b|\bassertion\b|\bstatement (I|1|one)\b/i.test(String(t))});
  if(!pin){var h=2166136261,str=OPSALT+ck;for(i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619)}
    var rnd=function(){h|=0;h=h+0x6D2B79F5|0;var t=Math.imul(h^h>>>15,1|h);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296};
    for(i=n-1;i>0;i--){var j=Math.floor(rnd()*(i+1)),x=p[i];p[i]=p[j];p[j]=x}}
  return OPC[ck]=p}
function optAt(key,o,i){var k=optPm(key,o).indexOf(i);return k<0?i:k}

/* ---------- storage: browser copy + private cloud copy on the signed-in account ---------- */
function fix(s){var d=EMPTY();Object.keys(d).forEach(function(k){if(s[k]==null)s[k]=d[k]});Object.keys(NM).forEach(function(p){if(!s.l[p])s.l[p]=1});return s}
try{var lc=JSON.parse(localStorage.getItem('coach1'));if(lc&&lc.ev)S=fix(lc)}catch(e){}
var wq=null,wt=null;
/* which copy wins: the one saved last. A device that has never synced does not get to replace a fuller cloud copy. */
var CR=false;
function synSeen(){try{return localStorage.getItem('coach1_syn')==='1'}catch(e){return false}}
function synMark(){try{localStorage.setItem('coach1_syn','1')}catch(e){}}
function svNewer(r,l){var a=+(r&&r.sv)||0,b=+(l&&l.sv)||0,re=((r&&r.ev)||[]).length,le=((l&&l.ev)||[]).length;
  if(!synSeen()&&re>=le)return true;if(a||b)return a>=b;return re>=le}
function save(){
  if(S.ev.length>300)S.ev=S.ev.slice(-300);S.sv=Date.now();
  try{localStorage.setItem('coach1',JSON.stringify(S))}catch(e){}
  if(!DOC)return;clearTimeout(wt);wt=setTimeout(push,800);
}
function push(){if(wq){wt=setTimeout(push,500);return}
  /* never write to the cloud before the cloud copy has been read once: a slow start must not replace saved progress with a blank one */
  if(!CR){var D1=DOC;wq=DOC.get().then(function(sn){if(D1!==DOC){wq=null;return}if(sn.exists){var r=JSON.parse(sn.data().s||'{}');if(r.ev&&svNewer(r,S)){S=fix(r);try{localStorage.setItem('coach1',JSON.stringify(S))}catch(e){}try{render()}catch(e){}}}CR=true;synMark();wq=null;clearTimeout(wt);wt=setTimeout(push,50)},function(){wq=null;clearTimeout(wt);wt=setTimeout(push,5000)});return}
  wq=DOC.set({s:JSON.stringify(S),at:Date.now()}).then(synMark,function(){}).then(function(){wq=null})}
(async function(){
  try{
    var db=await claude.use('db'),u=await claude.use('user');if(!db||!u)return;
    var id=await u.id();if(!id)return;DB=db;window.SBDB=db;window.SBUID=id;DOC=db.doc('data/users/'+id+'/'+sbDocName());var D0=DOC;if(window.sbOnDb)sbOnDb();
    var snap=await Promise.race([DOC.get(),new Promise(function(_,r){setTimeout(function(){r(new Error('timeout'))},10000)})]);if(D0!==DOC)return;
    if(snap.exists){var r=JSON.parse(snap.data().s||'{}');
      if(r.ev&&svNewer(r,S)){S=fix(r);try{localStorage.setItem('coach1',JSON.stringify(S))}catch(e){}CR=true;synMark();if(!mode||view!=='practice')render()}
      else{CR=true;synMark();save()}}
    else{CR=true;if(S.ev.length)save()}
  }catch(e){}
})();
async function getS(){if(SMP)return SMP;var s=await claude.use('sample');if(s)SMP=s;return s}
function sampleErr(e){return e&&e.code==='rate_limited'?'Claude is busy. Wait a minute and try again.':e&&e.code==='not_granted'?'Claude needs your permission for this. Allow it from the page’s Permissions menu.':'Claude could not finish that. Try again in a moment.'}

