var GRP={home:[['today','Today'],['base','Cover the base'],['spots','Progress']],learn:[['th','Theory'],['tl','Templates'],['st','Strategy'],['ex','Examples'],['story','Stories']],prac:[['practice','Chapters'],['lz','Lazy mode'],['cb','Concepts'],['pp','Papers']],check:[['check','Check notebook']],rev:[['mc','Cards'],['mk','Mistakes'],['nt','Notes']],subj:[['sj_eco','Economics'],['sj_pol','Pol. Science'],['sj_soc','Sociology'],['sj_his','History'],['sj_en1','English I'],['sj_en2','English II'],['sj_ele','Elective']],set:[['set','Settings'],['log','Usage log']]};
var GLAST={};
function grpOf(v){var g='home';Object.keys(GRP).forEach(function(k){GRP[k].forEach(function(t){if(t[0]===v)g=k})});return g}
/* tapping the section you are already in goes back to its start screen */
function viewTop(v){if(v==='th')TV.c=null;if(v==='tl'){TLF.c=null;TLF.f=null;TLF.p=null}if(v==='sj_his'){HV.c=null;HV.ret=null}if(v.indexOf('sj_')===0){SJV.p=null;SJV.rv=null;SJV.qz=null;SJV.mm=null}if(v==='st'){STV.c=null;STV.p=null;STV.dr=null}else if(v==='ex')EXI=null;else if(v==='pp')PPI=null;else if(v==='mk')MKR=null;else if(v==='mc')MCV.rv=null;else if(v==='cb')CBS=null;else if(v==='nt'){NTV.open=null;NTV.ed=null;NPAD=null}else if(v==='lz'){LZS.c=null;LZS.run=null}else if(v==='practice'){mode=null;GEN=null}}
function goView(v){if(v===view)viewTop(v);if(v!=='practice'){mode=null;GEN=null}view=v;render();window.scrollTo(0,0)}
document.querySelectorAll('.tab').forEach(function(b){b.onclick=function(){var g=this.getAttribute('data-g'),v=GLAST[g]||GRP[g][0][0];if(grpOf(view)===g)v=GRP[g].some(function(t){return t[0]===view})?view:v;goView(v)}});
function subBar(){var g=grpOf(view),T=GRP[g],el=document.getElementById('sub');GLAST[g]=view;
  el.innerHTML=T.length>1?'<div class="segs" role="tablist">'+T.map(function(t){var on=t[0]===view,n=t[0]==='mk'?mkList().filter(function(m){return!m.fx}).length:t[0]==='mc'?mcAll().filter(function(m){return mcHeat(m)>=3}).length:0;
    return'<button role="tab" aria-selected="'+on+'" onclick="goView(\''+t[0]+'\')">'+t[1]+(n?' <small>'+n+'</small>':'')+'</button>'}).join('')+'</div>':'<div class="subt">'+T[0][1]+'</div>';
  var open=mkList().filter(function(m){return!m.fx}).length,bd=document.getElementById('revBadge');if(bd){bd.hidden=!open;bd.textContent=open>99?'99+':open}}
function render(){
  if(window.__boot)return;
  if(typeof stStop==='function')stStop();applyPrefs();
  var g=grpOf(view);document.querySelectorAll('.tab').forEach(function(b){b.setAttribute('aria-current',b.getAttribute('data-g')===g)});subBar();
  if(view==='today')todayView();else if(view==='practice')home();else if(view==='check')checkView();else if(view==='story')storyView();else if(view==='ex')exView();else if(view==='base')baseView();else if(view==='pp')ppView();else if(view==='cb')cbView();else if(view==='mk')mkView();else if(view==='st')stView();else if(view==='mc')mcView();else if(view==='nt')ntView();else if(view==='lz')lzView();else if(view==='sj_his')hisView();else if(view.indexOf('sj_')===0)sjView(view.slice(3));else if(view==='th')thView();else if(view==='tl')tlView();else if(view==='set')setView();else if(view==='log')logView();else spotsView();
}

