/* ---------- other subjects: chapter banks (ISC Class XI syllabus, with NCERT Class 11 depth where topics overlap) ---------- */
var SCB=[];
(function(){var sub=null,ch=null,n=0;SCB_SRC.split('\n').forEach(function(l){l=l.trim();if(!l)return;
  if(l[0]==='@'){sub=l.slice(1);return}
  var p=l.split('|');
  if(p[0][0]==='#'){ch={id:p[0].slice(1),n:p[1],src:p[2]||'',sub:sub,k:[],q:[],m:[]};SCB.push(ch);n=0;return}
  if(!ch)return;
  if(p[0]==='k')ch.k.push({id:p[1],n:p[2],s:p[3]});
  else if(p[0]==='q'){var o=p.slice(4,8),a=0;o=o.map(function(x,i){if(x[0]==='*'){a=i;return x.slice(1)}return x});n++;
    ch.q.push({id:ch.id+'q'+n,k:p[1],l:+p[2],q:p[3],o:o,a:a,s:[p[8]||''],t:o.map(function(x,i){return i===a?'':'That option does not fit the key idea. Compare it with the explanation below.'})})}
  else if(p[0]==='m')ch.m.push([p[1],(p[2]||'').split(';').map(function(x){return x.trim()}).filter(Boolean)])})})();
function scbOf(sid){return SCB.filter(function(c){return c.sub===sid})}
function scbX(id){S.cbx=S.cbx||{};return S.cbx[id]||[]}
function cbCh(id){var c=CB.filter(function(c){return c.id===id})[0];if(c)return c;
  var s=SCB.filter(function(c){return c.id===id})[0];if(!s)return null;var x=scbX(id);return x.length?Object.assign({},s,{q:s.q.concat(x)}):s}
function cbBackTo(s){if(s){view='sj_'+s;SJV.p=null;SJV.rv=null;SJV.qz=null;SJV.mm=null}render();window.scrollTo(0,0)}
function sjChNames(sid){return scbOf(sid).map(function(c){return c.n})}
function sjMkOpen(sid){var n=sjSub(sid).n,cn=sjChNames(sid);return mkList().filter(function(m){return!m.fx&&(m.topic===n||cn.indexOf(m.topic)>=0)}).length}
function sjBankN(sid){return scbOf(sid).reduce(function(a,c){return a+cbCh(c.id).q.length},0)}
/* subject cards on the subject page */
function sjStudyCards(id){var C=scbOf(id);if(!C.length)return'';var hasC=typeof claude!=='undefined'&&claude&&claude.use;
  var cr=C.reduce(function(a,c){var f=cbFill(c);return[a[0]+f.n,a[1]+f.t]},[0,0]);
  var h='<div class="card cbcard"><span class="cbcap">Concept Builder</span><p class="sub" style="margin:8px 0 10px">Adaptive concept questions on each chapter of the ISC syllabus. Questions get harder as you get them right. '+cr[0]+' of '+cr[1]+' concepts cracked.</p><div class="cbmini">';
  C.forEach(function(c){h+='<button class="cbm" onclick="cbOpen(\''+c.id+'\')">'+cbRing(c,40)+'<small>'+esc(c.n.length>22?c.n.slice(0,21)+'…':c.n)+'</small></button>'});
  h+='</div></div>';
  h+='<div class="card"><div class="sjhd"><b>📝 Quick MCQs</b><span class="pill mid">'+sjBankN(id)+' questions</span></div><p class="sub" style="margin:4px 0 0">Ten mixed questions from every chapter. Wrong answers go to My mistakes.</p><div class="row2"><button class="btn" onclick="sjQzOpen(\''+id+'\')">10 mixed questions</button><button class="btn alt" onclick="sjQzOpen(\''+id+'\',1)">From my weak chapters</button></div>';
  if(hasC)h+='<label class="sub" for="sjXc" style="display:block;margin:10px 0 0">Add fresh questions from Claude</label><select id="sjXc">'+C.map(function(c){return'<option value="'+c.id+'">'+esc(c.n)+' ('+cbCh(c.id).q.length+')</option>'}).join('')+'</select><button class="btn alt" id="sjXb" onclick="sjMore(\''+id+'\')">✨ Add 6 new questions to this chapter</button><div id="sjXm" class="sub" style="margin:6px 0 0"></div>';
  h+='</div>';
  h+='<div class="card"><b>🧠 Memory maps</b><p class="sub" style="margin:4px 0 8px">One map per chapter: the big idea in the middle, branches around it. Use Test me to hide the details and recall them.</p><div class="chips">'+C.map(function(c){return'<button class="chipb" onclick="sjMmOpen(\''+id+'\',\''+c.id+'\')">'+esc(c.n)+'</button>'}).join('')+'</div></div>';
  return h}
/* quick MCQ quiz */
function sjQzOpen(sid,weak){var C=scbOf(sid),pool=[];C.forEach(function(c){var cc=cbCh(c.id),w=1;if(weak){var st=cbState(c);w=st.cls==='rd'?4:st.cls==='yl'?3:cbFill(c).n<cbFill(c).t?2:1}
    cc.q.forEach(function(q){for(var i=0;i<w;i++)pool.push({c:c.id,q:q})})});
  for(var i=pool.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),t=pool[i];pool[i]=pool[j];pool[j]=t}
  var seen={},pick=[];pool.forEach(function(x){if(pick.length<10&&!seen[x.q.id]){seen[x.q.id]=1;pick.push(x)}});
  view='sj_'+sid;SJV.p=null;SJV.rv=null;SJV.mm=null;SJV.qz={sid:sid,q:pick,i:0,pick:null,ok:0,wrong:[]};render();window.scrollTo(0,0)}
function sjQz(){var Z=SJV.qz,s=sjSub(Z.sid);var h='<p class="back"><button class="link" onclick="SJV.qz=null;render()">← '+esc(s.n)+'</button></p><h1>Quick MCQs</h1>';
  if(Z.i>=Z.q.length){h+='<div class="card hi"><b>'+Z.ok+' / '+Z.q.length+' right</b><p class="sub" style="margin:4px 0 0">'+(Z.wrong.length?'Missed ones are saved in My mistakes. Chapters to revisit: '+esc(Z.wrong.filter(function(v,i,a){return a.indexOf(v)===i}).join(', '))+'.':'All correct. Try the Concept Builder for harder questions.')+'</p><div class="row2"><button class="btn" onclick="sjQzOpen(\''+Z.sid+'\')">Ten more</button><button class="btn alt" onclick="SJV.qz=null;render()">Done</button></div></div>';app.innerHTML=h;return}
  var x=Z.q[Z.i],c=cbCh(x.c),q=x.q,kk=c.k.filter(function(k){return k.id===q.k})[0]||{n:'',s:''},done=Z.pick!=null,ok=done&&Z.pick===q.a;
  h+='<div class="meta"><span>'+esc(c.n)+'</span><span>'+(Z.i+1)+' / '+Z.q.length+'</span></div><div class="bar"><i style="width:'+(Z.i/Z.q.length*100)+'%"></i></div><div class="card"><div class="q">'+esc(q.q)+'</div>';
  optPm('cb:'+q.id,q.o).forEach(function(i,dj){var o=q.o[i];var cl='';if(done){if(i===q.a)cl=' ok';else if(i===Z.pick)cl=' bad'}h+='<button class="opt'+cl+'" onclick="sjQzAns('+i+')"'+(done?' disabled':'')+'>('+'abcd'[dj]+') '+esc(o)+'</button>'});
  if(done){h+='<div class="fb '+(ok?'ok':'bad')+'"><b>'+(ok?'Correct.':'Not quite. The answer is ('+'abcd'[optAt('cb:'+q.id,q.o,q.a)]+').')+'</b> '+esc(q.s.join(' '))+'</div>';
    if(kk.n)h+='<div class="pivot" style="margin-top:8px"><b>'+esc(kk.n)+'.</b> '+esc(kk.s)+'</div>';
    h+='<button class="btn" onclick="SJV.qz.i++;SJV.qz.pick=null;render();window.scrollTo(0,0)">'+(Z.i+1<Z.q.length?'Next question':'See my score')+'</button><button class="btn alt chatb" onclick="sjQzDoubt()">'+CHAT_ICON+'Ask a doubt in Claude chat</button>'}
  app.innerHTML=h+'</div>'}
function sjQzAns(i){var Z=SJV.qz;if(Z.pick!=null)return;var x=Z.q[Z.i],c=cbCh(x.c),q=x.q,ok=i===q.a,kk=c.k.filter(function(k){return k.id===q.k})[0]||{n:''};Z.pick=i;
  if(ok){Z.ok++;mkFix('cb:'+q.id)}else{Z.wrong.push(c.n);mkAdd({src:'Quick MCQs',topic:c.n,concept:kk.n,q:q.q,o:q.o,a:q.a,pick:i,h:q.s.join(' '),note:sjSub(Z.sid).n,ref:'cb:'+q.id})}
  S.ev.push({k:'q',topic:c.n,ok:ok,habit:ok?'':'Concept: '+kk.n,type:'quick mcq',ts:Date.now()});save();sjKeep()}
function sjQzDoubt(){var Z=SJV.qz,x=Z.q[Z.i],c=cbCh(x.c),q=x.q;openChat(chatHead()+sjSub(Z.sid).n+' · '+c.n+'\nQuestion: '+q.q+'\nOptions: '+q.o.map(function(o,i){return'('+'abcd'[i]+') '+o}).join(' | ')+'\nI chose ('+'abcd'[Z.pick]+'); the answer is ('+'abcd'[q.a]+') '+q.o[q.a]+'.\nApp’s explanation: '+q.s.join(' ')+'\n\nMy doubt: ')}
/* memory maps */
function sjMmOpen(sid,cid){view='sj_'+sid;SJV.p=null;SJV.rv=null;SJV.qz=null;SJV.mm={sid:sid,c:cid,hide:0,open:{}};render();window.scrollTo(0,0)}
function sjMm(){var M=SJV.mm,C=scbOf(M.sid),i=C.map(function(c){return c.id}).indexOf(M.c),c=C[i],s=sjSub(M.sid);
  var h='<p class="back"><button class="link" onclick="SJV.mm=null;render()">← '+esc(s.n)+'</button></p><h1>Memory map</h1><p class="sub">'+esc(c.src)+'</p>';
  h+='<div class="seg" role="tablist"><button role="tab" aria-selected="'+!M.hide+'" onclick="SJV.mm.hide=0;render()">Show all</button><button role="tab" aria-selected="'+!!M.hide+'" onclick="SJV.mm.hide=1;SJV.mm.open={};render()">Test me</button></div>';
  h+='<div class="mmap"><div class="mmc">'+esc(c.n)+'</div><div class="mmb">';
  c.m.forEach(function(b,bi){var shown=!M.hide||M.open[bi];h+='<div class="mmbr c'+(bi%5+1)+'"><button class="mmh" onclick="'+(M.hide?'SJV.mm.open['+bi+']=!SJV.mm.open['+bi+'];render()':'')+'"'+(M.hide?'':' tabindex="-1"')+'>'+esc(b[0])+(M.hide?' <small>'+(shown?'hide':'tap to recall')+'</small>':'')+'</button>'+(shown?'<div class="mml">'+b[1].map(function(l){return'<span>'+esc(l)+'</span>'}).join('')+'</div>':'<div class="mml mmq">'+b[1].map(function(){return'<span>?</span>'}).join('')+'</div>')+'</div>'});
  h+='</div></div>';
  h+='<div class="card"><b>Key concepts</b>'+c.k.map(function(k){return'<div class="person"><b>'+esc(k.n)+'</b><br><small>'+esc(k.s)+'</small></div>'}).join('')+'<div class="row2"><button class="btn" onclick="cbOpen(\''+c.id+'\')">Practise this chapter</button><button class="btn alt" onclick="sjMmOpen(\''+M.sid+'\',\''+C[(i+1)%C.length].id+'\')">Next map →</button></div></div>';
  app.innerHTML=h}
/* Claude adds fresh questions in the Concept Builder format */
async function sjMore(sid){if(busy)return;var sel=document.getElementById('sjXc'),b=document.getElementById('sjXb'),m=document.getElementById('sjXm'),cid=sel&&sel.value,c=cid&&SCB.filter(function(x){return x.id===cid})[0];if(!c)return;
  busy=true;b.disabled=true;m.textContent='Claude is writing new questions…';
  try{var s=await getS();if(!s)throw new Error('none');var have=cbCh(cid).q.map(function(q){return'- '+q.q}).join('\n');
    var d=await s.json('Write 6 new multiple-choice questions for ISC Class XI '+sjSub(sid).n+', chapter “'+c.n+'” ('+c.src+'). Follow the ISC syllabus, with NCERT Class 11 depth where it overlaps. Concepts (use these ids):\n'+c.k.map(function(k){return k.id+': '+k.n+' – '+k.s}).join('\n')+'\nDo not repeat these existing questions:\n'+have+'\nMix levels: 2 at level 1 (recall), 2 at level 2 (understanding), 2 at level 3 (apply or analyse a short case). Four options each, one clearly correct, distractors plausible. Keep every fact accurate; leave out anything uncertain. Use neutral wording for the student.\nReturn JSON only: {"q":[{"k":"concept id","l":1,"q":"question","o":["a","b","c","d"],"a":index of correct option,"s":"one or two sentence explanation"}]}',{cache:false,modelTier:'default'});
    var ids=c.k.map(function(k){return k.id}),L=scbX(cid).slice(),n=L.length,add=0;
    (d&&d.q||[]).forEach(function(x){if(!x||!x.q||!x.o||x.o.length!==4||!(x.a>=0&&x.a<4))return;n++;add++;
      L.push({id:cid+'x'+Date.now().toString(36)+n,k:ids.indexOf(x.k)>=0?x.k:ids[0],l:Math.max(1,Math.min(3,+x.l||2)),q:String(x.q),o:x.o.map(String),a:+x.a,s:[String(x.s||'')],t:x.o.map(function(o,i){return i===+x.a?'':'That option does not fit the key idea. Compare it with the explanation below.'})})});
    if(!add)throw new Error('shape');S.cbx[cid]=L.slice(-60);save();sjKeep();var mm=document.getElementById('sjXm');if(mm)mm.textContent=add+' new questions added to '+c.n+'. They now appear in Concept Builder and Quick MCQs.'}
  catch(e){m.textContent=e&&e.code?sampleErr(e):'Claude couldn’t add questions just now. Try again in a moment.'}
  finally{busy=false;var bb=document.getElementById('sjXb');if(bb)bb.disabled=false}}

/* ---------- stories ---------- */
var STT=['Complex Numbers','Permutations and Combinations','Binomial Theorem','Sequences and Series','Straight Lines','Circles','Conic Sections','Trigonometric Functions','Quadratic Equations','Probability','Statistics','Three-dimensional Geometry','Limits and Derivatives'];
var ANG=[['history','History of the idea'],['life','A mathematician’s life'],['world','Where it shows up today']],SANG='history',STORY=null;
function storyView(){
  var h='<h1>Stories</h1><p class="sub">Real people and real history behind the maths: who found it, why it mattered, and where you meet it now.</p>';
  h+='<div class="card"><label for="stTopic"><b>Chapter</b></label><select id="stTopic">'+STT.map(function(t){return'<option>'+t+'</option>'}).join('')+'</select>';
  h+='<b>Angle</b><div class="chips" style="margin:6px 0 4px">'+ANG.map(function(a){return'<button class="chipb'+(a[0]===SANG?' on':'')+'" data-a="'+a[0]+'">'+a[1]+'</button>'}).join('')+'</div>';
  h+='<button class="btn" id="stGo">Tell me a story</button><div id="stMsg" class="sub" style="margin:8px 0 0"></div></div><div id="stOut"></div>';
  app.innerHTML=h;
  if(STORY){document.getElementById('stTopic').value=STORY.topic;drawStory()}
  document.querySelectorAll('[data-a]').forEach(function(b){b.onclick=function(){SANG=b.dataset.a;document.querySelectorAll('[data-a]').forEach(function(x){x.classList.toggle('on',x===b)})}});
  document.getElementById('stGo').onclick=tellStory;
}
async function tellStory(){
  if(busy)return;var m=document.getElementById('stMsg'),b=this,topic=document.getElementById('stTopic').value;busy=true;b.disabled=true;m.textContent='Claude is digging into the history…';
  try{
    var s=await getS();if(!s){m.textContent='Claude is not available here. Open the app while signed in to claude.ai.';return}
    var seen=(S.st||[]).slice(-15).join('; ');
    var ang=SANG==='life'?'Tell the life story of ONE real mathematician whose work shaped this topic: their background, struggles, a turning point, and what they found.':SANG==='world'?'Show where this topic is used in the real world today, through one or two concrete, true examples.':'Tell how this idea was discovered and developed: the problem people were trying to solve, who was involved, across which cultures and centuries (include Indian mathematicians where they genuinely contributed).';
    var d=await s.json('You tell true, vivid stories about mathematics to a teenage student, to help them love the subject. Topic: '+topic+'.\n'+ang+intLine()+'\nACCURACY RULES: use only well-documented historical facts. Give dates as approximate where historians disagree. Never invent quotes, scenes or anecdotes; if a famous story is legend or disputed, say so. Leave out any detail you are not sure of.'+(seen?'\nAlready told (pick a different story): '+seen:'')+'\nReturn JSON only: {"title":"under 9 words","people":[{"name":"","years":"e.g. c. 598–668 CE","role":"one line"}] (1-3 people),"story":"200-260 words, warm and lively, short paragraphs separated by blank lines","today":"2-3 sentences linking it to the student’s world","did_you_know":"one surprising true fact","check":{"q":"a fun question about the story or the maths in it","o":["","",""],"a":index of correct,"why":"one sentence"},"read_more":"a real book, museum page or documentary title to explore further, or empty"}',{cache:false,modelTier:'complex'});
    if(!d||!d.story)throw new Error('shape');
    STORY={topic:topic,d:d,pick:null};S.st=(S.st||[]).concat(String(d.title)).slice(-40);save();
    m.textContent='';drawStory();b.textContent='Another story';
  }catch(e){m.textContent=e&&e.code?sampleErr(e):'That didn’t come through. Try again.'}
  finally{busy=false;b.disabled=false}
}
function drawStory(){var o=document.getElementById('stOut');if(!o||!STORY)return;var d=STORY.d,x=d.check;
  var h='<div class="card story"><h2>'+esc(d.title)+'</h2>';
  (d.people||[]).forEach(function(p){h+='<div class="person"><b>'+esc(p.name)+'</b> <small>'+esc(p.years||'')+'</small><br><span class="muted">'+esc(p.role||'')+'</span></div>'});
  h+='<div class="ctext" style="margin-top:10px">'+esc(d.story)+'</div>';
  if(d.today)h+='<div class="claude" style="margin-top:12px"><b>In your world</b><br>'+esc(d.today)+'</div>';
  if(d.did_you_know)h+='<p style="margin:12px 0 0"><b>Did you know?</b> '+esc(d.did_you_know)+'</p>';
  if(x&&x.q&&Array.isArray(x.o)){h+='<div class="qc"><b>Quick question:</b> '+esc(x.q)+'</div>';
    optPm('st:'+x.q,x.o).forEach(function(k){var op=x.o[k];var cl=STORY.pick==null?'':k===x.a?' ok':k===STORY.pick?' bad':'';h+='<button class="opt sm'+cl+'" data-sk="'+k+'"'+(STORY.pick!=null?' disabled':'')+'>'+esc(op)+'</button>'});
    if(STORY.pick!=null)h+='<div class="fb '+(STORY.pick===x.a?'ok':'bad')+'">'+(STORY.pick===x.a?'<b>Yes!</b> ':'<b>Not quite.</b> ')+esc(x.why||'')+'</div>'}
  if(d.read_more)h+='<p class="sub" style="margin:12px 0 0">Explore more: '+esc(d.read_more)+'</p>';
  h+='<button class="btn alt chatb" id="stChat">'+CHAT_ICON+'Explore this story in Claude chat</button></div>';
  h+='<p class="sub">Claude checks its facts, but history can be disputed. Treat dates as approximate.</p>';
  o.innerHTML=h;
  o.querySelectorAll('[data-sk]').forEach(function(b){b.onclick=function(){STORY.pick=+b.dataset.sk;drawStory()}});
  document.getElementById('stChat').onclick=function(){openChat('I just read a short story about the history of '+STORY.topic+': "'+d.title+'" ('+(d.people||[]).map(function(p){return p.name}).join(', ')+'). I’d love to explore it further. Tell me more about the people and the ideas, how it connects to what I’m learning in maths, and show me one problem they would have worked on. Please stick to well-documented facts and say when something is legend or disputed.'+(S.int?' I enjoy '+S.int+'.':''))};
}

function waLink(){return'https://wa.me/'+(S.tw||'')+'?text='+encodeURIComponent(tutorText())}
/* ---------- open in Claude chat ---------- */
var LASTQ=null,LASTD=null,CHAT_ICON='<svg viewBox="0 0 24 24" aria-hidden="true" class="ci"><path d="M4 5h16v11H9l-5 4z"/></svg>';
function chatHead(){return'I’m practising maths and want to understand this properly. Please tutor me step by step: ask me questions and give hints before showing full answers, check my reasoning, and use a similar example if I’m stuck.'+(S.int?' I enjoy '+S.int+', so examples from those are welcome.':'')+'\n\n'}
function openChat(t){
  if(t.length>6000)t=t.slice(0,6000)+'…';
  try{navigator.clipboard&&navigator.clipboard.writeText(t).catch(function(){})}catch(e){}
  var w=null;try{w=window.open('https://claude.ai/new?q='+encodeURIComponent(t),'_blank')}catch(e){}
  showToast(w?'Opening Claude chat. The details are also copied: if the box is empty, just paste.':'Copied. Open a new Claude chat and paste it in.');
}
function showToast(t){var d=document.createElement('div');d.className='toast';d.setAttribute('role','status');d.textContent=t;document.body.appendChild(d);setTimeout(function(){d.remove()},4500)}
function chatQ(){var x=LASTQ;if(!x)return;
  openChat(chatHead()+'Topic: '+x.topic+'\nQuestion: '+x.q+'\nOptions: '+x.o.join(' | ')+'\n'+(x.ok?'I chose the right answer ('+x.ans+') but want to understand it better.':'I chose '+x.pick+', but the answer is '+x.ans+'. My practice app says my likely slip is: '+x.habit+'.')+'\nApp’s short method: '+x.h+'\n\nHelp me see where my thinking went wrong, then give me a couple of similar questions to try.')}
function chatD(){var x=LASTD;if(!x)return;var d=x.d;
  openChat(chatHead()+'Topic: '+x.topic+'\nProblem: '+(d.problem||'')+'\nMy working, step by step:\n'+(d.steps||[]).map(function(s,i){return(i+1)+'. '+s.text}).join('\n')+'\n'+(d.error_type==='none'?'The app said this is all correct.':'The app flagged step '+(d.first_error_step||'?')+' ('+(d.error_type||'')+'): '+(d.what_went_wrong||'')+'\nHabit: '+(d.habit||''))+'\n\nLet’s go through it together. Start by asking me what I think went wrong.')}
function chatP(){var p=document.getElementById('prob').value.trim()||(BOOK&&BOOK.text)||'';
  if(!p){document.getElementById('msg').textContent='Type the question in the box above first.';return}
  var hist=CH.map(function(x){return'- '+(x.kind==='hint'?'Hint '+x.lvl:x.kind==='explain'?'Explanation':'Step check')+': '+x.reply.replace(/\n+/g,' ')}).join('\n');
  openChat(chatHead()+'Topic: '+document.getElementById('topic').value+'\nProblem: '+p+'\n'+(hist?'\nWhat my practice app’s tutor has said so far:\n'+hist+'\n':'')+'\nI may attach a photo of my handwritten working. Let’s continue from where I am.')}

/* ---------- weak spots ---------- */
function summary(){
  var qs=S.ev.filter(function(e){return e.k==='q'}),nb=S.ev.filter(function(e){return e.k==='nb'});
  var byT={};qs.forEach(function(e){var k=NM[e.p]||e.p;byT[k]=byT[k]||[0,0];byT[k][1]++;if(e.ok)byT[k][0]++});
  var hab={};S.ev.forEach(function(e){var t=e.k==='q'?e.tag:e.habit;if(!e.ok&&t){var k=tg(t)[0];hab[k]=(hab[k]||0)+1}});
  return{qs:qs,nb:nb,byT:byT,hab:hab};
}
function spotsView(){
  var m=summary(),acc=m.qs.length?Math.round(m.qs.filter(function(e){return e.ok}).length/m.qs.length*100):0;
  var h='<h1>Weak spots</h1><p class="sub">Everything answered or photographed feeds this profile. Claude reads the whole history and explains the pattern.</p>';
  h+=wkCard();
  h+=sjProgCard();
  h+='<div class="stats"><div class="stat"><b>'+m.qs.length+'</b><span>questions</span></div><div class="stat"><b>'+(m.qs.length?acc+'%':'–')+'</b><span>correct</span></div><div class="stat"><b>'+m.nb.length+'</b><span>notebook checks</span></div></div>';
  var newN=S.ev.length-S.anN;
  h+='<div class="card hi cl"><b>Claude’s diagnosis</b>';
  if(S.an){h+='<p class="sub" style="margin:2px 0 8px">Written '+new Date(S.anAt).toLocaleString()+(newN>0?' · '+newN+' new answers since':'')+'</p><div class="claude">'+anHtml(S.an)+'</div>'}
  else h+='<p class="sub" style="margin:4px 0 0">'+(S.ev.length<5?'After about 10 answers or a couple of notebook checks, Claude can describe the weak spots and why they happen.':'Ready for a first diagnosis.')+'</p>';
  h+='<button class="btn" id="an"'+(S.ev.length<5?' disabled':'')+'>'+(S.an?'Update the diagnosis':'Diagnose weak spots')+'</button><div id="am" class="sub" style="margin:8px 0 0"></div></div>';
  var T=Object.keys(m.byT);
  if(T.length){h+='<div class="card"><b>Accuracy by chapter</b>';T.sort(function(a,b){return m.byT[a][0]/m.byT[a][1]-m.byT[b][0]/m.byT[b][1]}).forEach(function(k){var v=m.byT[k],p=Math.round(v[0]/v[1]*100);
    h+='<div class="tbar"><span>'+esc(k)+'</span><div class="tr"><i style="width:'+p+'%;background:'+(p<50?'var(--bad)':p<75?'var(--accent)':'var(--ok)')+'"></i></div><em>'+v[0]+'/'+v[1]+'</em></div>'});h+='</div>'}
  var H=Object.keys(m.hab).sort(function(a,b){return m.hab[b]-m.hab[a]});
  if(H.length){h+='<div class="card"><b>Habits behind the mistakes</b>';H.slice(0,8).forEach(function(k){h+='<div class="spot"><b>'+esc(k)+'</b> <small>('+m.hab[k]+'×)</small></div>'});h+='</div>'}
  h+='<div class="card"><b>Send progress to the tutor</b><p class="sub" style="margin:4px 0 0">A short report: accuracy by topic, main slips and Claude’s diagnosis.</p><pre id="rep">'+esc(tutorText())+'</pre><div class="wabar"><a class="btn wa" id="wa" target="_blank" rel="noopener" href="'+waLink()+'">'+WAI+(S.tw?'Send to teacher':'Send on WhatsApp')+'</a><button class="btn alt" id="cpr">Copy</button></div><div id="cpm" class="sub" style="margin:8px 0 0"></div><p class="sub" style="margin:8px 0 0">Teacher’s number, interests and reset are in <button class="link" onclick="goView(\'set\')">⚙ Settings</button>.</p></div>';
  h+='<div class="card cl"><b>Install on the phone</b><p class="sub" style="margin:4px 0 0">Open this page in Chrome while signed in to claude.ai, tap ⋮, then <b>Add to Home screen</b>. On iPhone use Safari’s Share button, then <b>Add to Home Screen</b>. Progress is saved to the signed-in Claude account, so it follows you across devices.</p></div>';
  h+='<div class="note cl">Claude accounts are for adults 18 and over. Run this on a parent’s or tutor’s account and sit with the student, or set it up on their device under your supervision.</div>';
  app.innerHTML=h;
  document.getElementById('an').onclick=analyse;
  document.getElementById('cpr').onclick=function(){var m=document.getElementById('cpm'),t=tutorText();try{navigator.clipboard.writeText(t).then(function(){m.textContent='Copied. Paste it into any chat.'},function(){m.textContent='Press and hold the report to copy it.'})}catch(e){m.textContent='Press and hold the report to copy it.'}};
}
function tutorText(){var m=summary(),t='Study Buddy progress ('+new Date().toLocaleDateString()+')\n';
  var T=Object.keys(m.byT);if(!T.length&&!m.nb.length)return t+'No practice yet.';
  T.forEach(function(k){t+='• '+k+': '+m.byT[k][0]+'/'+m.byT[k][1]+' correct\n'});
  if(m.nb.length)t+='• Notebook checks: '+m.nb.length+'\n';
  var H=Object.keys(m.hab).sort(function(a,b){return m.hab[b]-m.hab[a]}).slice(0,4);if(H.length)t+='\nMain slips: '+H.map(function(k){return k+' ('+m.hab[k]+'×)'}).join(', ')+'\n';
  if(S.an){t+='\nClaude’s diagnosis: '+S.an.summary+'\n';(S.an.weaknesses||[]).forEach(function(w){t+='– '+w.name+': '+w.fix+'\n'});if(S.an.for_tutor)t+='\nFor the tutor: '+S.an.for_tutor}
  return t}
function anHtml(a){
  var h='<p style="margin:0 0 8px">'+esc(a.summary)+'</p>';
  (a.weaknesses||[]).forEach(function(w){h+='<div class="spot" style="margin:8px 0"><b>'+esc(w.name)+'</b><br><small>Evidence: '+esc(w.evidence)+'</small><br>Why: '+esc(w.cause)+'<br>Fix: '+esc(w.fix)+'</div>'});
  if(a.strengths)h+='<p style="margin:8px 0"><b>Going well:</b> '+esc(a.strengths)+'</p>';
  if(a.plan&&a.plan.length){h+='<b>Next steps</b><ol style="margin:4px 0 0;padding-left:20px">';a.plan.forEach(function(p){h+='<li>'+esc(p)+'</li>'});h+='</ol>'}
  if(a.for_tutor)h+='<p style="margin:10px 0 0"><b>For the tutor:</b> '+esc(a.for_tutor)+'</p>';
  return h;
}
async function analyse(){
  if(busy)return;var m=document.getElementById('am'),b=this;busy=true;b.disabled=true;m.textContent='Claude is reading the full history…';
  try{
    var s=await getS();if(!s){m.textContent='Claude is not available here. Open the app while signed in to claude.ai.';return}
    var sm=summary(),lines=[];
    Object.keys(sm.byT).forEach(function(k){lines.push(k+': '+sm.byT[k][0]+'/'+sm.byT[k][1]+' correct')});
    var hab=Object.keys(sm.hab).map(function(k){return k+' ×'+sm.hab[k]}).join('; ');
    var rec=S.ev.slice(-60).map(function(e){return e.k==='q'?(e.ok?'✓ ':'✗ ')+(NM[e.p]||e.p)+' L'+e.l+': '+e.q+(e.ok?'':' | chose '+e.pick+' | habit: '+tg(e.tag)[0]):'notebook '+e.topic+': '+(e.ok?'correct':e.type+' error, habit: '+e.habit)}).join('\n');
    var a=await s.json('You are an experienced maths tutor reviewing a student’s practice history.\nAccuracy by topic:\n'+lines.join('\n')+'\nMistake habits with counts: '+(hab||'none')+'\nRecent activity, oldest first (✓ correct, ✗ wrong; "chose" is the wrong pick):\n'+rec+'\n\nFind the real underlying weaknesses, not just topic names: look for the same error across topics (signs, formula recall, reading the question, arithmetic) and whether recent answers show improvement. Base every claim on the evidence shown; if the data is thin, say so. Write warmly and plainly to a student and tutor. Return JSON only: {"summary":"2-3 sentences","weaknesses":[{"name":"short label","evidence":"what in the data shows it","cause":"likely reason","fix":"one concrete fix"}] (max 3, worst first),"strengths":"one sentence","plan":["3-4 specific next steps for the next few days"],"for_tutor":"one or two sentences on what to watch for in person"}',{modelTier:'complex',cache:false});
    if(!a||!a.summary)throw new Error('shape');
    S.an=a;S.anAt=Date.now();S.anN=S.ev.length;save();spotsView();
  }catch(e){m.textContent=e&&e.code?sampleErr(e):'Claude’s diagnosis came back in the wrong shape. Try again.';b.disabled=false}
  finally{busy=false}
}
